codeExample.bad:
/* Removes the focus indicator entirely with no replacement,
   leaving keyboard users with no way to see their position */
:focus {
  outline: none;
}

codeExample.good:
/* Replaces the default outline with a custom but clearly visible
   focus style instead of removing it outright */
:focus-visible {
  outline: 3px solid #1a73e8;
  outline-offset: 2px;
}
